// W modularnym monolicie (1 wspolna baza) - 1 transakcja obejmuje oba kroki (Lesson13)
void placeOrderMonolith(SimulatedTransaction tx) {
    tx.record("reserveStock");
    tx.record("chargePayment");
    tx.commit(); // WSZYSTKO albo NIC - gwarantowane przez baze danych
}

// Miedzy mikroserwisami (osobne bazy) - potrzebna Saga z KROKIEM KOMPENSUJACYM
void placeOrderSaga(InventoryService inventory, PaymentService payment) {
    inventory.reserveStock("SKU-1");
    try {
        payment.charge(100.0);
    } catch (Exception e) {
        inventory.releaseStock("SKU-1"); // REKOMPENSATA - recznie "cofamy" 1. krok
    }
}

